 static void Visual(int pedido,int separado)
 {
  admin.CrearMesa(++numero,4);var reservaMesa=admin.ListarMesas().Single(m=>m.Numero==numero);admin.ReservarMesa(new(Guid.NewGuid(),reservaMesa.Id,"Reserva ficticia visible para todo el equipo"));
  using(var inicio=new FormularioPrincipal(admin,new ConfiguracionConexionTemporal(cadena),admin.UsuarioActual!)){Mostrar(inicio);Esperar(()=>!inicio.UseWaitCursor&&inicio.Controls.Find("btnVerReserva_"+admin.ConsultarReservaMesa(reservaMesa.Id)!.Id,true).Length>0);Capturar(inicio,"inicio-reservas");Ok(true,"Inicio presenta reservas activas con acceso a consulta");inicio.Close();}

  using(var f=new FormularioCobranza(admin,pedido)){Mostrar(f);Esperar(()=>f.Controls.Find("lblResumen",true).OfType<Label>().Any(l=>l.Text.Contains("SALDO")));Capturar(f,"cobranza-abonos");var pestanas=f.Controls.Find("tabConsumoAbonos",true).OfType<TabControl>().Single();pestanas.SelectedIndex=1;Capturar(f,"historial-abonos");pestanas.SelectedIndex=0;Ok(f.Controls.Find("btnConfirmar",true).Single().Visible,"Cobranza muestra acción real de abono");f.Close();}
  using(var f=new FormularioDivision(admin,admin.RevisarCuenta(Nuevo()))){Mostrar(f);Esperar(()=>f.Controls.Find("dgvPartes",true).OfType<DataGridView>().Single().Rows.Count==2);Capturar(f,"separar-cuentas");f.Close();}
  using(var f=new FormularioGestionMesa(admin,admin.ListarMesas().Single(m=>m.Id==admin.RevisarCuenta(pedido).MesaId))){Mostrar(f);Esperar(()=>f.Controls.Find("btnCobrarSaldo",true).Length>0);Capturar(f,"opciones-cierre");f.Close();}
  using(var f=new FormularioComprobante(admin.ConsultarReciboAbono(admin.ConsultarCobranza(pedido).Abonos.First().OperacionId))){Mostrar(f);Capturar(f,"recibo-abono");f.Close();}
  using(var f=new FormularioPromocion(admin)){Mostrar(f);Application.DoEvents();Capturar(f,"promocion");f.Close();}
  using(var f=new FormularioDetalleMesa(admin,admin.ListarMesas().Single(m=>m.Id==admin.RevisarCuenta(pedido).MesaId))){Mostrar(f);Esperar(()=>f.Controls.Find("lblResumen",true).OfType<Label>().Any(l=>l.Text.Contains("Pedido")));var cobro=f.Controls.Find("btnRevisarCobro",true).Single();var tabla=f.Controls.Find("dgvDetalles",true).Single();Ok(cobro.Height<120*f.DeviceDpi/96&&tabla.Height>=100,"Comanda mantiene tabla y botón de cobro sin expansión desproporcionada");Capturar(f,"mesa-pedido");f.Close();}
 }
 static void Mostrar(Form f){f.StartPosition=FormStartPosition.Manual;f.Location=new(0,0);f.Size=new(1366,900);f.Show();SynchronizationContext.SetSynchronizationContext(new WindowsFormsSynchronizationContext());Application.DoEvents();}
 static void Capturar(Form f,string n){Application.DoEvents();using var b=new Bitmap(f.Width,f.Height);f.DrawToBitmap(b,new(Point.Empty,b.Size));b.Save(Path.Combine(salida,n+".png"));Console.WriteLine($"CAPTURA {n}; DPI {f.DeviceDpi}");}
 static void Esperar(Func<bool> c){var start=DateTime.UtcNow;while(!c()){if((DateTime.UtcNow-start).TotalSeconds>40)throw new TimeoutException();Application.DoEvents();Thread.Sleep(10);}Application.DoEvents();}
 static SolicitudCobro Datos(CuentaRevision c,Guid id,decimal importe,string metodo,decimal entregado,string estado="Confirmado")=>new(id,c.PedidoId,c.Version,importe,true,"Público general",null,null,null,metodo,entregado,estado,"Referencia ficticia",null,true,true,metodo=="Cortesía");
 static SolicitudAbono Abono(RepositorioRestaurante repo,int p,decimal importe,string metodo="Efectivo",decimal? entregado=null,string estado="Confirmado",int? cuentaId=null){var c=repo.ConsultarCobranza(p);var saldo=cuentaId.HasValue?c.Cuentas.Single(x=>x.Id==cuentaId).Saldo:c.Saldo;var id=Guid.NewGuid();return new(id,p,c.Pedido.Version,c.Pedido.Total,cuentaId,saldo,importe,Datos(c.Pedido,id,importe,metodo,entregado??importe,estado));}
 static int Nuevo(int? cliente=null){admin.CrearMesa(++numero,4);var mesa=admin.ListarMesas().Single(m=>m.Numero==numero);if(!admin.ListarMenu().Any(m=>m.Nombre=="Producto ficticio diez"))admin.GuardarProducto(null,"Producto ficticio diez","Ensayo","Plato",10,false);var producto=admin.ListarMenu().Single(m=>m.Nombre=="Producto ficticio diez");return admin.CrearPedido(new(){MesaId=mesa.Id,ClienteId=cliente,Detalles=[new(producto.Id,3)]}).Id;}
 static string Estado(int pedido)=>admin.ListarMesas().Single(m=>m.Id==admin.RevisarCuenta(pedido).MesaId).Estado;
 static RepositorioRestaurante Repo(string u,string? clave=null){var r=new RepositorioRestaurante(new ConfiguracionConexionTemporal(cadena));if(r.IniciarSesion(u,clave??Clave)is null)throw new Exception("Sesión de fixture inválida");return r;}
 static void Ok(bool v,string m){if(!v)throw new Exception("FALLO "+m);checks++;Console.WriteLine("OK "+m);}
 static void Deniega(Action a,string m){try{a();}catch(Exception e)when(e is ArgumentException or InvalidOperationException or UnauthorizedAccessException or SqlException){Ok(true,m);return;}throw new Exception("No rechazó: "+m);}
 static string Escalar(string sql){using var c=new SqlConnection(cadena);c.Open();using var q=new SqlCommand(sql,c);return Convert.ToString(q.ExecuteScalar())!;}
 static int Numero(string sql)=>int.Parse(Escalar(sql));
 static void Sql(string sql)=>En(cadena,sql);
 static void En(string cs,string sql){using var c=new SqlConnection(cs);c.Open();using var q=new SqlCommand(sql,c){CommandTimeout=120};q.ExecuteNonQuery();}
}
